/**
 * Display label for a broadcast. Uses the Broadcast Titles tab title when one
 * exists; otherwise a factual date-based label ("X Broadcast — August 26, 2026")
 * so the page never renders empty headings. This is a descriptor, not a title —
 * real titles still come only from the sheet and blanks still fail the sync.
 */
const MONTH_NAMES = [
  "January", "February", "March", "April", "May", "June",
  "July", "August", "September", "October", "November", "December",
];

export function displayTitleFor(broadcast: XBroadcast): string {
  const real = broadcast.title?.trim();
  if (real) return real;
  const m = broadcast.date?.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (m) {
    const month = MONTH_NAMES[Number(m[2]) - 1] ?? m[2];
    return `X Broadcast — ${month} ${Number(m[3])}, ${m[1]}`;
  }
  return "X Broadcast Replay";
}

export function extractReplayHlsUrl(html: string): string | null {
  const normalized = html
    .replaceAll("\\u0026", "&")
    .replaceAll("\\/", "/")
    .replaceAll("&amp;", "&");
  const matches = normalized.match(/https:\/\/[^"'<>\s]+\.m3u8(?:\?[^"'<>\s]*)?/g) ?? [];
  return matches.find(url => url.includes("periscope-replay") || url.includes("type=replay")) ?? matches[0] ?? null;
}
